import{_ as e,C as i,o as s,c as o,E as n,a2 as r}from"./chunks/framework.CkaEw-3u.js";const m=JSON.parse('{"title":"Luaスクリプトで動かす（Scripting）","description":"Lua 5.4スクリプトで毎フレームの文字・パーツをプロシージャルに制御するスクリプティング機能の使い方","frontmatter":{"title":"Luaスクリプトで動かす（Scripting）","description":"Lua 5.4スクリプトで毎フレームの文字・パーツをプロシージャルに制御するスクリプティング機能の使い方","pageClass":"feature-guide","aside":false,"head":[["link",{"rel":"canonical","href":"https://mug-lab-3.github.io/mug-typography-docs/features/feature-scripting.html"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mug Typography Manual"}],["meta",{"property":"og:locale","content":"ja_JP"}],["meta",{"property":"og:title","content":"Luaスクリプトで動かす（Scripting） | Mug Typography Manual"}],["meta",{"property":"og:description","content":"Lua 5.4スクリプトで毎フレームの文字・パーツをプロシージャルに制御するスクリプティング機能の使い方"}],["meta",{"property":"og:url","content":"https://mug-lab-3.github.io/mug-typography-docs/features/feature-scripting.html"}],["meta",{"property":"og:image","content":"https://mug-lab-3.github.io/mug-typography-docs/image/social-card.png"}],["meta",{"property":"og:image:type","content":"image/png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:image:alt","content":"Mug Typography Online Manual"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:site","content":"@MugLab3"}],["meta",{"name":"twitter:title","content":"Luaスクリプトで動かす（Scripting） | Mug Typography Manual"}],["meta",{"name":"twitter:description","content":"Lua 5.4スクリプトで毎フレームの文字・パーツをプロシージャルに制御するスクリプティング機能の使い方"}],["meta",{"name":"twitter:image","content":"https://mug-lab-3.github.io/mug-typography-docs/image/social-card.png"}],["meta",{"name":"twitter:image:alt","content":"Mug Typography Online Manual"}]]},"headers":[],"relativePath":"features/feature-scripting.md","filePath":"features/feature-scripting.md"}'),p={name:"features/feature-scripting.md"};function l(c,t,d,h,g,k){const a=i("FeatureHero");return s(),o("div",null,[n(a,{"is-new":"",eyebrow:"LUA SCRIPTING",title:"スクリプトで文字を動かす",description:"波打ち、ランダム散らし、物理風の動きなど、キーフレームでは作りにくいアニメーションを短いスクリプトで実現。付属のVSCode用シミュレーターを使えば、DaVinci Resolveを起動せずに開発・プレビューできます。",image:"/image/scripting-hero.webp","image-alt":"Luaスクリプトで制御された文字アニメーション","detail-link":"/reference/reference-scripting-settings","point-one":"毎フレームをコードで制御","point-two":"VSCodeシミュレーター付属","point-three":"豊富なサンプルスクリプト"}),t[0]||(t[0]=r(`<h2 id="使い方" tabindex="-1">使い方 <a class="header-anchor" href="#使い方" aria-label="Permalink to &quot;使い方&quot;">​</a></h2><p>通常の2D / 3D / Liteプリセットでは、次の手順で有効にします。</p><ol><li><strong>Page</strong> を <code>Scripting</code> にします。</li><li><strong>Script Enabled</strong> をONにします。</li><li><strong>Script Text</strong> にLuaスクリプトを入力するか、<strong>Paste Script</strong> でクリップボードから貼り付けます。</li></ol><p><code>Mug Typography Scripting</code>プリセットでは、Scriptingグループが<strong>Globalページ内</strong>に表示されるため、Pageの切り替えは不要です。このプリセットはCharacter SettingsとPart Settingsを省略して最大512文字・1024パーツを扱え、個々の文字・パーツはLuaから制御します。インスペクタでの個別編集とLuaを併用したい場合は、通常のプリセットを使用してください。</p><p>たとえば次のスクリプトだけで、全文字がそれぞれ位相をずらしながら揺れ続けます。</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> OnLayout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> index, character </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mt.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">each_char</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">do</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        character.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rotation</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> math.sin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">time</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2.0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> index </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 15.0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        character.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">offset_y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> math.sin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">time</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3.0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> index </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.02</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    end</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">end</span></span></code></pre></div><p>スクリプトはインスペクタの値を毎フレーム上書きする形で動作します。キーフレームや他の機能（デフォーム、Write On、3Dなど）とそのまま併用できます。</p><h2 id="_4つのコールバック" tabindex="-1">4つのコールバック <a class="header-anchor" href="#_4つのコールバック" aria-label="Permalink to &quot;4つのコールバック&quot;">​</a></h2><p>スクリプトには最大4つの関数を定義できます。どれも省略可能です。</p><table tabindex="0"><thead><tr><th>コールバック</th><th>タイミング</th><th>主な用途</th></tr></thead><tbody><tr><td><code>OnInitialize(ctx)</code></td><td>スクリプトロード時に1回</td><td>チャンクスコープの<code>local</code>変数へ保存する定数の事前計算</td></tr><tr><td><code>OnPreLayout(ctx)</code></td><td>レイアウト確定<strong>前</strong>（毎フレーム）</td><td>テキスト・字送り・整列・全体色・カメラなど基礎値の変更</td></tr><tr><td><code>OnLayout(ctx)</code></td><td>レイアウト確定<strong>後</strong>（毎フレーム）</td><td>文字ごと・パーツごとの位置、回転、スケール、色などの調整</td></tr><tr><td><code>OnPath(ctx)</code></td><td><code>OnLayout</code>後（毎フレーム）</td><td><code>ctx.paths</code>で必要なパーツだけを選び、正規化されたSVG互換パスやベジェ曲線で輪郭を置換</td></tr></tbody></table><p>「Base（基礎値）を確定し、そこから生成された文字・パーツを調整する」という二段階が基本モデルです。文字数に影響する変更（タイプライター演出など）は <code>OnPreLayout</code>、個々の文字を動かす演出は <code>OnLayout</code> に書きます。</p><p><code>mt.*</code> 名前空間には <code>mt.each_char</code> / <code>mt.each_part</code>（対象の反復）、<code>mt.clamp</code> / <code>mt.lerp</code> / <code>mt.remap</code>（数値計算）、<code>mt.ease.*</code>（イージング）、<code>mt.color.*</code>（色操作）、<code>mt.timeline.*</code>（時間制御）、<code>mt.svg_path</code>（再利用可能なSVG互換パス）などが用意されています。</p><h2 id="vscodeシミュレーター-mt-sim" tabindex="-1">VSCodeシミュレーター（MT Sim） <a class="header-anchor" href="#vscodeシミュレーター-mt-sim" aria-label="Permalink to &quot;VSCodeシミュレーター（MT Sim）&quot;">​</a></h2><p>配布ZIPの <code>scripting-simulator/</code> フォルダに、VSCode拡張「<strong>Mug Typography Scripting Simulator</strong>」（MT Sim）が同梱されています。ホストアプリを起動せずに、スクリプトの開発・プレビューが完結します。</p><ul><li><strong>インストール</strong>: VSCodeの拡張機能ビューで「Install from VSIX...」を選び、同梱の <code>.vsix</code> ファイルを指定します。</li><li><strong>起動</strong>: <code>.lua</code> ファイルを開き、エディタタイトルのプレビューアイコンかコマンドパレットの「Mug Typography Scripting Simulator」を実行します。ファイルを保存すると即座にリロードされます。</li><li><strong>プラグインへコピー</strong>: パネル上部の <strong>Copy Script</strong> で現在のLuaソースをコピーし、プラグインの <strong>Paste Script</strong> でScript Textへ貼り付けます。</li><li><strong>編集支援</strong>: <code>ctx.*</code> や <code>mt.*</code> の入力補完・ホバードキュメントが利用でき、コールバックごとに書き込み可能なフィールドだけが提示されます。</li><li><strong>シーン再現</strong>: タイムライン再生、フォント選択、文字・パーツ単位のインスペクタ、実効値の一覧表示、3Dプリセットのカメラプレビューまで再現します。</li></ul><div class="info custom-block"><p class="custom-block-title">Level 7サンプルにはMug Typography v5.1a以降が必要です</p><p>現在のMT Simと同梱サンプルはAPI Level 7を前提とします。配布ZIP同梱のVSCode拡張は対応するプラグインと組み合わせて使用してください。オンラインシミュレーターでは、更新済みであることを確認するまで案内が表示されます。</p></div><div class="warning custom-block"><p class="custom-block-title">シミュレーターは近似プレビューです</p><p>MT Simのレイアウトと描画はプラグイン本体の近似です。グラデーションの補間や投影後のストローク品質などは簡略化されているため、最終的な仕上がりは必ずMug Typography本体で確認してください。</p></div><h3 id="ブラウザで試す" tabindex="-1">ブラウザで試す <a class="header-anchor" href="#ブラウザで試す" aria-label="Permalink to &quot;ブラウザで試す&quot;">​</a></h3><p>インストール不要で、ブラウザからそのまま試せる<a href="https://mug-lab-3.github.io/mug-typography-docs/simulator/" target="_blank" rel="noreferrer"><strong>オンラインシミュレーター ↗</strong></a>も公開しています。VSCode拡張版と同じ編集支援・サンプル集を備え、ちょっとした動作確認やAPIの学習に手軽に使えます。</p><h3 id="作品をギャラリーに公開する" tabindex="-1">作品をギャラリーに公開する <a class="header-anchor" href="#作品をギャラリーに公開する" aria-label="Permalink to &quot;作品をギャラリーに公開する&quot;">​</a></h3><p>作ったアニメーションは、オンラインシミュレーターの<strong>ギャラリー</strong>に公開できます。公開された作品はサンプルブラウザの <strong>gallery</strong> タブに並び、誰でもカードから開いてスクリプトを読んだり、自分の制作の出発点にしたりできます。</p><p>投稿は<a href="https://github.com/mug-lab-3/mug-typography-community" target="_blank" rel="noreferrer"><strong>ギャラリーリポジトリ ↗</strong></a>から受け付けています（シミュレーターのメニューの <strong>Submit to Gallery</strong> からも開けます）。必要なファイルと手順はリポジトリのREADMEを参照してください。</p><h2 id="aiにスクリプトを書いてもらう" tabindex="-1">AIにスクリプトを書いてもらう <a class="header-anchor" href="#aiにスクリプトを書いてもらう" aria-label="Permalink to &quot;AIにスクリプトを書いてもらう&quot;">​</a></h2><p>Luaを書いたことがなくても、ChatGPTやClaudeなどのチャットAIに作りたい動きを伝えれば、 スクリプトを生成できます。ただしAIはMug Typographyの仕様を知らないため、 <strong>先にAI向けの仕様書を読み込ませる</strong>ことが必要です。これを省くと、 存在しない関数を使ったり、単位や向きを取り違えたスクリプトが返ってきます。</p><h3 id="手順" tabindex="-1">手順 <a class="header-anchor" href="#手順" aria-label="Permalink to &quot;手順&quot;">​</a></h3><ol><li><p><strong>仕様書を読み込ませる。</strong> 新しいチャットを開き、配布ZIPに同梱されている 次のファイルを<strong>添付</strong>して、「このAPI仕様書を読んでください」と伝えます。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scripting-simulator/docs/lua_api_for_ai.md</span></span></code></pre></div><p>ファイルを添付できないAIの場合は、テキストエディタで開いて全文を貼り付けてください。 Web上のファイルを読み取れるAIであれば、次のURLを渡す方法もあります （読み取りに対応していないAIも多いため、まずは添付をおすすめします）。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://mug-lab-3.github.io/mug-typography-docs/lua_api_for_ai.md</span></span></code></pre></div></li><li><p><strong>読み込めたか確認する。</strong> 仕様書は大きなファイルのため、AIによっては 添付が読まれないことがあります。続けて次のように聞いてください。</p><blockquote><p><code>mt.stagger</code> の引数を、単位も含めて教えてください。</p></blockquote><p><code>time</code>（秒）、<code>index</code>（1始まり）、<code>delay</code>（秒）、<code>duration</code>（秒）と 答えられれば、正しく読み込めています。答えられない場合は<a href="#うまくいかないときは">後述の対処</a>を行ってください。</p></li><li><p><strong>作りたいアニメーションを指示する。</strong> 日本語で構いません。具体的に伝えるほど 意図に近いものが返ってきます。</p><blockquote><p>文字が1つずつ下から跳ね上がって登場し、最後に全体がゆっくり揺れるアニメーションを作ってください。</p></blockquote><p>3D操作を一切使わない作品なら、「<strong>2D専用として作って</strong>」「<strong>2D限定にして</strong>」と明記できます。対応したAIは、3D対応のScriptingプリセットでも2D描画経路を使う指定をスクリプトへ追加します。3D投影処理を省けるため描画速度の向上が期待できますが、CameraやGlobalなどの3Dインスペクタ設定とキーフレームはすべて無効になります。あとから3D操作を加える可能性がある場合は、2D専用にしないでください。</p></li><li><p><strong>返ってきたコードをコピーし</strong>、<strong>Script Text</strong> に貼り付けるか、 <strong>Paste Script</strong> で読み込みます。</p></li><li><p><strong>思った動きと違う場合は、そのまま伝えて修正してもらいます。</strong> 「跳ね上がりをもっと強く」「揺れは不要」のように、続けて指示できます。</p></li></ol><h3 id="うまくいかないときは" tabindex="-1">うまくいかないときは <a class="header-anchor" href="#うまくいかないときは" aria-label="Permalink to &quot;うまくいかないときは&quot;">​</a></h3><p>手順2の確認に答えられない、存在しない関数が使われる、単位や向きが明らかにおかしい ——いずれも仕様書が読まれていないサインです。次の順に試してください。</p><ol><li><strong>新しいチャットを開いて添付し直す。</strong> 会話が長くなると、最初に添付した内容が 参照されにくくなります。仕様書を読ませた直後に指示するのが最も確実です。</li><li><strong>添付ではなく全文を貼り付ける。</strong> テキストエディタで仕様書を開き、 全選択してチャット欄に貼り付けます。添付より確実に読み込まれます。</li><li><strong>別のAIを試す。</strong> 手元のPCで動かす小型のAIでは、仕様書が大きすぎて 読み込めないことがあります。</li></ol><div class="tip custom-block"><p class="custom-block-title">動作確認はシミュレーターが便利です</p><p>生成されたスクリプトにエラーがあっても、本体側ではエラー内容を確認できません。 MT Simやオンラインシミュレーターに貼り付けると、エラーメッセージと行番号が表示されるので、 それをAIに伝えるとそのまま修正してもらえます。</p></div><h2 id="サンプルとapiリファレンス" tabindex="-1">サンプルとAPIリファレンス <a class="header-anchor" href="#サンプルとapiリファレンス" aria-label="Permalink to &quot;サンプルとAPIリファレンス&quot;">​</a></h2><p>配布ZIPの <code>scripting-simulator/samples/</code> に、そのまま使えるLuaサンプルが多数入っています。</p><ul><li><code>reference/</code> — 基本モデルとAPIを番号順に学ぶための短い学習用サンプル</li><li><code>showcase/</code> — タイプライター、バウンス登場、ネオン、3Dカメラワークなど完成品のアニメーションパターン集</li><li><code>diagnostics/</code> — 環境・APIの内部動作確認用スクリプト</li></ul><p><code>reference</code>は<code>01</code>〜<code>11</code>でコールバック、文字・パーツ、継承、レイアウトなどの 基本を学び、<code>12</code>以降で<code>mt.*</code>ユーティリティを目的別に確認できる構成です。同じ目的で パラメーターの組み合わせが重要なAPIは、1つのスクリプト内で設定を切り替えて比較できます。</p><p>オンラインシミュレーターのサンプルブラウザには、読む・改造するための <code>reference</code>・<code>showcase</code>・<code>gallery</code>だけが表示されます。Scripting機能が正常に 動作しているか確認する場合は、メニューの <strong>Scripting Check</strong> を実行してください。 編集中のスクリプトやシーンを変更せず、診断結果だけを表示します。</p><p>APIの完全な仕様は「<a href="/mug-typography-docs/scripting/api-reference.html">Luaスクリプティング APIリファレンス</a>」を参照してください。同じ仕様書は、オフライン用として配布ZIPの <code>scripting-simulator/docs/</code> にも同梱されています。</p><p>パラメーターの詳細と制限事項は「<a href="/mug-typography-docs/reference/reference-scripting-settings.html">スクリプティング設定 (Scripting Settings)</a>」を参照してください。</p>`,37))])}const y=e(p,[["render",l]]);export{m as __pageData,y as default};
